  "<html lang=\"en\">",
  "<head>",
  "<meta charset=\"utf-8\">",
  "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">",
  "<title>Cloudbite — Expert sandbox workspace</title>",
  "<meta name=\"description\" content=\"Several expert AI roles work on one shared project in separate workspaces, and their results are synthesised\">",
