  "  for (const e of p.experts) {",
  "    if (e.status === \"failed\") {",
  "      failed++;",
  "      continue;",
  "    }",
  "    if (e.status === \"cancelled\") {",
  "      cancelled++;",
  "      continue;",
  "    }",
  "    if (e.status !== \"completed\") {",
  "      pending++;",
  "      continue;",
  "    }",
  "    completed++;",
  "    const o = e.opinion;",
  "    if (!o) {",
  "      invalid++;",
  "      continue;",
  "    }",
  "    valid++;",
  "    counts[o.direction]++;",
  "    confSum += o.confidence;",
  "    buckets[Math.min(4, Math.floor(o.confidence / 20))]++;",
  "    const voice = { name: e.name, confidence: o.confidence, summary: o.summary };",
  "    if (o.direction === \"support\") supportVoices.push(voice);",
  "    if (o.direction === \"concern\") concernVoices.push(voice);",
  "    for (const a of o.nextActions) {",
  "      const key = a.replace(/\\s+/g, \" \").trim().toLowerCase();",
  "      const cur = actionMap.get(key);",
  "      if (cur) {",
  "        cur.count++;",
  "        if (!cur.names.includes(e.name)) cur.names.push(e.name);",
  "        cur.conf = Math.max(cur.conf, o.confidence);",
  "      } else actionMap.set(key, { text: a, count: 1, names: [e.name], conf: o.confidence });",
  "    }",
  "  }",
  "  const byConf = (a, b) => b.confidence - a.confidence;",
  "  supportVoices.sort(byConf);",
  "  concernVoices.sort(byConf);",
  "  let leading = null;",
  "  for (const d of DIRECTIONS) if (counts[d] > 0 && (leading === null || counts[d] > counts[leading])) leading = d;",
  "  const tie = leading !== null && DIRECTIONS.filter((d) => counts[d] === counts[leading]).length > 1;",
  "  const disagreement = counts.support > 0 && counts.concern > 0;",
  "  const actions = [...actionMap.values()].sort((a, b) => b.count - a.count || b.conf - a.conf).slice(0, 5).map(({ text, count, names }) => ({ text, count, names }));",
  "  let headline = m.hNone;",
  "  if (valid > 0 && leading) {",
  "    const base = tie ? m.hTie : leading === \"support\" ? m.hSupport : leading === \"conditional\" ? m.hConditional : leading === \"concern\" ? m.hConcern : m.hAbstain;",
  "    headline = valid < p.experts.length ? m.hPartial(base, valid, p.experts.length) : base;",
  "  }",
  "  return {",
  "    selected: p.experts.length,",
  "    completed,",
  "    valid,",
  "    invalid,",
  "    failed,",
  "    pending,",
  "    cancelled,",
  "    counts,",
  "    meanConfidence: valid ? Math.round(confSum / valid) : null,",
  "    buckets,",
  "    leading: tie ? null : leading,",
  "    disagreement,",
  "    supportVoices: supportVoices.slice(0, 2),",
  "    concernVoices: concernVoices.slice(0, 2),",
  "    actions,",
  "    headline",
  "  };",
  "}",
  "const DEMO_SOURCE = { repository: \"cloudbite built-in demo\", path: \"client/cloudbite-console.ts\", revision: \"demo\", license: \"demo\", basis: \"metadata-derived\" };",
  "const DEMO_EXPERTS = [",
