  "  if (/윤리|신뢰|ethic|trust|safety/.test(t)) return \"trust\";",
  "  if (/데이터|data|검증|analy/.test(t)) return \"data\";",
  "  if (/ux|사용자|디자인|design|research/.test(t)) return \"ux\";",
