  "}",
  "function markdownReport(p, demo, m = EN) {",
  "  const a = aggregate(p, m);",
  "  const lines = [",
  "    `# ${p.brief.title}`,",
  "    \"\",",
  "    demo ? m.mdDemo : m.mdLive,",
  "    \"\",",
  "    `## ${m.mdObjective}`,",
  "    p.brief.objective,",
  "    \"\",",
  "    `## ${m.mdContext}`,",
  "    p.brief.context || m.none,",
  "    \"\",",
  "    `## ${m.mdSynthesis}`,",
  "    `- ${m.mdStatus(m.projectStatus[p.status])}`,",
  "    `- ${m.mdCounts(a)}`,",
  "    `- ${DIRECTIONS.map((d) => `${m.direction[d]} ${a.counts[d]}`).join(\" · \")}`,",
  "    `- ${m.mdMean(a.meanConfidence === null ? \"—\" : a.meanConfidence + \"%\")}`,",
  "    \"\",",
  "    a.headline,",
  "    \"\",",
  "    `## ${m.mdNext}`,",
  "    ...a.actions.length ? a.actions.map((x, i) => `${i + 1}. ${x.text} (${x.names.join(\", \")})`) : [m.none],",
  "    \"\",",
  "    `## ${m.mdByExpert}`",
  "  ];",
  "  for (const e of p.experts) {",
  "    lines.push(\"\", `### ${e.name} — ${m.status[e.status]}`);",
  "    if (e.opinion) lines.push(m.mdOpinion(m.direction[e.opinion.direction], e.opinion.confidence), \"\", e.opinion.summary);",
  "    else if (e.error) lines.push(m.mdError(e.error));",
  "    else if (e.invalidOpinion) lines.push(m.mdInvalid);",
  "  }",
  "  return lines.join(\"\\n\") + \"\\n\";",
  "}",
